from lib import *
S = SS('j277')
steps = [
    step("哪些操作用一级缓存(同一个 EntityManager,Hibernate 6.6.4 + PostgreSQL 16):find(1) 第一次 +1 条 SQL,第二次与之后再 find 两次都是 +0;JPQL 按主键查同一行 +1,按唯一字段 code 查 +1,count 聚合 +1——JPQL 总是访问数据库;getReference(1)(已在缓存里)+0;find 一个不存在的主键 999 三次 +3(没有负缓存);先用 JPQL 把 bob 查出来,再 find(2) +0 且是同一个对象(JPQL 的结果也进入一级缓存)。“查询不再访问数据库”只适用于按主键的 find / getReference。", t=tl(S(1)), done=lidx(S(1), 'find(1) 第一次', 'find(1) 第二次', '再 find 两次'), mark=lidx(S(1), 'JPQL 按主键查同一行', 'JPQL 按唯一字段', 'getReference(1)', '999', 'count 聚合', 'bob 查出来'), b=bars([['find 第二次', 0, '+0'], ['JPQL 按主键', 1, '+1'], ['find 不存在的 id × 3', 3, '+3']], 3, done=[0, 1, 2]), kv=KV([['find / getReference(已缓存)', '不发 SQL'], ['任何 JPQL(含按主键)', '一定发 SQL'], ['不存在的主键', '每次都查,没有负缓存']], ['任何 JPQL(含按主键)'])),
    step("陈旧数据:EntityManager 加载 alice(age = 30),另一个连接(JDBC)提交了 age = 99、name = ALICE-DB。当前 EntityManager 里 find(1) 仍得到 age = 30;重新发 JPQL 查询(SQL 确实发给了数据库),返回的对象与缓存里的是同一个,z.age = 30、z.name = alice——数据库里已经是新值,返回的却是缓存里的旧实体;只查字段(投影)select p.age, p.name 直接读数据库,得到 99、ALICE-DB;em.refresh(x) 之后 age = 99;另一次修改后 em.clear() 再 find 得到新值 100。", t=tl(S(2)), done=lidx(S(2), '加载 alice', 'find(1):age = 30', 'JPQL 重新查询'), mark=lidx(S(2), '投影', 'em.refresh', 'em.clear()'), kv=KV([['find / JPQL 返回实体', '仍是缓存里的旧值(age = 30)'], ['投影查询', '读到新值(99)'], ['refresh / clear', '重新加载,得到新值']], ['find / JPQL 返回实体'])),
    step("陈旧缓存 + 修改 = 丢失更新(没有 @Version):EntityManager 1 加载 alice(age = 10),另一个连接把 age 改成 77 并提交;EntityManager 1 只改了 name 并 commit,之后库里 age = 10、name = alice-renamed——UPDATE 带上了所有列,把别人写的 age = 77 覆盖回了 10。一级缓存里的快照只是加载时的样子,Hibernate 并不知道别人改过。", t=tl(S(3)), done=lidx(S(3), 'EntityManager 1 加载 alice', '另一个连接把 age 改成 77'), mark=lidx(S(3), 'age = 10,name = alice-renamed'), kv=KV([['另一个连接', '提交 age = 77'], ['EntityManager 1 只改 name 并 commit', '库里 age 被覆盖回 10']], ['EntityManager 1 只改 name 并 commit'])),
    step("缓存里的实体不会自己释放:读 100,002 行(每行约 400 字节)。一个 EntityManager 全部留着:堆内存 10 → 92 MiB(+82 MiB),耗时 723 ms,随机一行 contains = true;每 1000 个 em.clear():堆内存回到 10 MiB(+0),耗时 526 ms;StatelessSession(没有一级缓存):+0 MiB,耗时 343 ms。大批量读取不清理缓存,内存与行数成正比。", t=tl(S(4)), done=lidx(S(4), '加载前堆内存', '托管实体不清理'), mark=lidx(S(4), '每 1000 个 em.clear()', 'StatelessSession'), b=bars([['不清理:+MiB', 82, '+82 MiB'], ['每 1000 个 clear:+MiB', 0, '+0 MiB'], ['StatelessSession:+MiB', 0, '+0 MiB']], 82, done=[0, 1, 2]), kv=KV([['不清理', '+82 MiB,723 ms'], ['每 1000 个 clear()', '+0 MiB,526 ms'], ['StatelessSession', '+0 MiB,343 ms']], ['不清理'])),
]
A = mkartj('j277', 277, 'Java,JPA,Hibernate,一级缓存,陈旧数据,丢失更新,PostgreSQL,真实验证,动画演示',
    '在 Hibernate 6.6.4 + 真实 PostgreSQL 上实测 JPA 一级缓存:只有 find / getReference 命中缓存,所有 JPQL 都发 SQL,但返回的是缓存里的旧实体(另一个连接已改成 99 仍看到 30);只改 name 的提交会把别人写的 age 覆盖回旧值;读 10 万行不清理缓存堆内存 +82 MiB,每 1000 个 clear 或 StatelessSession 为 +0。',
    '“一级缓存让查询不再访问数据库”只对一小部分操作成立,而且它带来的陈旧数据和内存问题常被忽略。这篇用真实的 SQL 计数、另一个连接的并发修改和 10 万行的堆内存测量,量出它的行为。',
    [('+0 / +1', '同一个 EntityManager 里第二次 find 与同一行的 JPQL 查询新增的 SQL 数'), ('30 vs 99', '另一个连接已把 age 改成 99 后,JPQL 重新查询返回的实体的 age(缓存里的旧值)与投影查询读到的 age'), ('+82 MiB vs +0', '读 100,002 行不清理缓存与每 1000 个 em.clear() 的堆内存增量')],
    [('哪些操作命中缓存', None), ('陈旧数据', None), ('丢失更新', None), ('内存', None)],
    steps, [ENV_J + '。Hibernate ORM 6.6.4.Final、PostgreSQL JDBC 42.7.4、本机 PostgreSQL 16.15(默认 READ COMMITTED);另一个并发事务用 JDBC 直接提交;堆内存取 System.gc() 之后的 used,-Xmx1g', '没有验证:二级缓存(hibernate.cache.use_second_level_cache)与查询缓存、@Version 乐观锁(下一篇)、REPEATABLE READ / SERIALIZABLE 隔离级别下的同一场景、@DynamicUpdate、Spring 的 OpenEntityManagerInView 对缓存生命周期的影响'], 'JPA 一级缓存')
